const successMessage = document.getElementById('successMessage');

const fullNameError = document.getElementById('fullNameError');
const emailError = document.getElementById('emailError');
const phoneError = document.getElementById('phoneError');

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const phoneRegex = /^[\s()+-]*(\d[\s()+-]*){10,}$/;

function validateFullName(value) {
    if (value.trim().length === 0) {
        return 'Full name is required.';
    }
    if (value.trim().length < 2) {
        return 'Full name must be at least 2 characters.';
    }
    return '';
}

function validateEmail(value) {
    if (value.trim().length === 0) {
        return 'Email address is required.';
    }
    if (!emailRegex.test(value)) {
        return 'Please enter a valid email address.';
    }
    return '';
}

function validatePhone(value) {
    if (value.trim().length === 0) {
        return '';
    }
    if (!phoneRegex.test(value)) {
        return 'Please enter a valid phone number.';
    }
    return '';
}

function showError(input, errorElement, message) {
    if (message) {
        input.classList.add('error');
        input.classList.remove('success');
        errorElement.textContent = message;
        errorElement.classList.add('show');
    } else {
        input.classList.remove('error');
        if (input.value.trim().length > 0) {
            input.classList.add('success');
        }
        errorElement.textContent = '';
        errorElement.classList.remove('show');
    }
}

fullNameInput.addEventListener('blur', () => {
    const error = validateFullName(fullNameInput.value);
    showError(fullNameInput, fullNameError, error);
});

fullNameInput.addEventListener('input', () => {
    if (fullNameError.classList.contains('show')) {
        const error = validateFullName(fullNameInput.value);
        showError(fullNameInput, fullNameError, error);
    }
});

emailInput.addEventListener('blur', () => {
    const error = validateEmail(emailInput.value);
    showError(emailInput, emailError, error);
});

emailInput.addEventListener('input', () => {
    if (emailError.classList.contains('show')) {
        const error = validateEmail(emailInput.value);
        showError(emailInput, emailError, error);
    }
});

phoneInput.addEventListener('blur', () => {
    const error = validatePhone(phoneInput.value);
    showError(phoneInput, phoneError, error);
});

phoneInput.addEventListener('input', () => {
    if (phoneError.classList.contains('show')) {
        const error = validatePhone(phoneInput.value);
        showError(phoneInput, phoneError, error);
    }
});

form.addEventListener('submit', (e) => {
    e.preventDefault();

    const fullNameError_msg = validateFullName(fullNameInput.value);
    const emailError_msg = validateEmail(emailInput.value);
    const phoneError_msg = validatePhone(phoneInput.value);

    showError(fullNameInput, fullNameError, fullNameError_msg);
    showError(emailInput, emailError, emailError_msg);
    showError(phoneInput, phoneError, phoneError_msg);

